import re,glob,collections
c=collections.Counter()
for f in glob.glob('**/*',recursive=True):
    if not f.endswith(('.ts','.html')):continue
    s=open(f).read()
    for m in re.finditer(r'<app-icon-button\b[^>]*>',s):
        t=m.group(0)
        if not re.search(r'label',t,re.I):
            c[re.sub(r'\s+',' ',t)]+=1
for k,v in c.most_common():print(v,k)
